#!/usr/bin/env python3
"""Promote the index-7/2 Lane–Emden headline, its simulator, certificates and existence proof from
Work/Math to Checked/Math (run 2026-11-20T0428Z; promote_le72.py of run 2026-11-19T2228Z with the index changed and the
data in five parts; LEGStart is already in Checked). The headline docstring is the promoted index-five-halves one with
the numbers changed (its wording passed the claim-vocabulary checks), written into the Work file too.

Mechanical copy: namespaces Work.Math -> Checked.Math, `import Mathlib` -> specific modules, module docs
replaced by number-free text (check_prose rule 7). Statements and proofs otherwise byte-identical."""
import pathlib
ROOT = pathlib.Path(__file__).resolve().parents[3]
W, C = ROOT / "Work/Math", ROOT / "Checked/Math"
MODS = ["LE92Cell", "LE92CellQ", "LE92Glue", "LE92QDataP0", "LE92QDataP1", "LE92QDataP2", "LE92QDataP3", "LE92QData", "LE92Chain",
        "LaneEmden92", "LE92ExistsLeft", "LE92ExistsRight", "LE92Exists"]
G = "`runs/2026-11-20T0428Z/scripts/emit_le92.py`"
P = "Promoted verbatim from `Work/Math/{m}.lean`."
DATA = "the singular start and the validated cells of the Lane–Emden chain of index nine halves as data; every side condition, defect bound and link decided by kernel evaluation over the rationals, one declaration per segment of cells."
DOCS = {
 "LE92Cell": "Lane–Emden equation of index nine halves: the nonlinearity θ to the power nine halves as `g92 θ`, the ninth power of the square root (equal to Mathlib's real power for every real θ, `rpow92_eq`), its Lipschitz bound on a slab (`g92_lip`), the closeness of `g92 x` to the ninth power of `y` from a certificate that the square of `y` is close to `x` (`g92_close`), and the validated cell step `cell` in the norm that weighs the derivative φ by a positive weight `w` (Grönwall for the field of θ and w times φ, generic tube lemma `Checked.Math.LENCell.tube_cell_t`): with weight one it is the cell of the earlier indices; a larger weight removes the floor one on the Lipschitz constant of the unweighted norm, so the enclosure no longer grows exponentially on the long range to the first zero.",
 "LE92CellQ": "Lane–Emden equation of index nine halves: the validated cells of `Checked.Math.LE92Cell.cell` checked by kernel evaluation. All side conditions and both defect bounds of a cell are one proposition over the rationals (`CellProp`); the power of the Taylor polynomial is replaced in the defect by the ninth power of a polynomial `pw` whose square is certified close to it and which is bounded away from zero, and in a cell next to the zero of θ (`pw` empty) it is bounded crudely. Each cell carries its own weight of φ; the links between cells rescale the radius by the ratio of the weights (`linkOK`).",
 "LE92Glue": "Lane–Emden equation of index nine halves: the singular start (`start92`, the generic start of `Checked.Math.LEGStart` with a residual certified through the square-root polynomial) and the last cell (`last92`: sign change of θ, φ negative, bounds on the mass factor, read in the weighted norm of the cell), each from one proposition over the rationals decided by kernel evaluation; `qeqB` compares coefficient lists with order relations only.",
 "LE92QDataP0": f"Generated by {G}, first of five parts: {DATA}",
 "LE92QDataP1": f"Generated by {G}, second of five parts: {DATA}",
 "LE92QDataP2": f"Generated by {G}, third of five parts: {DATA}",
 "LE92QDataP3": f"Generated by {G}, fourth of five parts: {DATA}",
 "LE92QData": f"Generated by {G}, last of five parts (the data are split because one module of all cells ran out of memory locally): {DATA}",
 "LE92Chain": f"Generated by {G}: chaining of the singular start, the kernel-checked segments and the last cell of the Lane–Emden chain of index nine halves.",
 "LE92ExistsLeft": "Lane–Emden equation of index nine halves, existence near the centre: Banach fixed point of the scaled Volterra map with the power nine halves clamped closer to one than in the index-three construction `Checked.Math.LEExistsLeft` and the Lipschitz constant of the contraction raised from nine halves to six (the contraction factor is unchanged).",
 "LE92ExistsRight": "Lane–Emden equation of index nine halves, existence away from the centre: Picard–Lindelöf for the clamped field; the clamped energy is nonincreasing and the potential part is not negative, so the clamp on φ stays inactive, and the bound on θ' keeps the clamp on θ inactive (adapted from `Checked.Math.LEExistsRight`).",
 "LE92Exists": "Lane–Emden equation of index nine halves: existence of a solution meeting every hypothesis of `Checked.Math.LaneEmden92.laneEmden92_constants` (left piece by a fixed point, right piece by Picard–Lindelöf for the clamped field with the clamps inactive by the energy, glued).",
}
NEWDOC = """/-- Lane–Emden equation θ'' + (2/ξ)θ' + θ ^ (9/2) = 0: for every solution θ on (0, 32] with
θ(0) = 1, θ differentiable on [0, 32] with derivative φ, and φ continuous at 0, there is a zero ξ₁ of
θ with 31.836463 ≤ ξ₁ ≤ 31.836464 and θ > 0 on [0, ξ₁), at which −ξ₁² θ'(ξ₁) lies between
1.7377988 and 1.7377989 and ξ₁³/(3 · (−ξ₁² θ'(ξ₁))) lies between 6189.4730 and 6189.4733. -/"""
WF = W / "LaneEmden92.lean"
w = WF.read_text()
if "/-- Lane–Emden equation of index 9/2" in w:   # first run only (the freeze's docstring)
    a = w.index("/-- Lane–Emden equation of index 9/2"); b = w.index("-/", a) + 2
    w = w[:a] + NEWDOC + w[b:]
assert NEWDOC in w
w = w.replace("its fifth derivative in θ blows up there", "its fifth derivative in θ is unbounded there")
w = w.replace(" The first zero lies near 31.8, three times further out than at index seven halves.", " The first zero lies about three times further out than at index seven halves.")
w = w.replace("""

**Proof.** A chain of 146 validated cells from the singular start at ξ = 1/2 to the bracket
[31.8364631, 31.8364634] of the zero (`Work.Math.LE92Certs.chain`), in the weighted norm
max(|Δθ|, w |Δφ|) with w = 1, 4, 10, 20 from ξ = 0, 4, 8, 16 (`Work.Math.LE92Cell.cell`): in the
unweighted max norm the enclosure grows like e^ξ and reaches 3 · 10⁻⁴ at the zero.""", """

**Proof.** A chain of validated cells from the singular start to a bracket of the zero
(`Work.Math.LE92Certs.chain`), in the norm that weighs φ by a weight growing along the chain
(`Work.Math.LE92Cell.cell`): in the unweighted norm the enclosure grows exponentially along the
range and no longer decides the sign of θ at the ends of the bracket.""")
w = w.replace("""Reference (floating point, not evidence): `runs/2026-11-20T0428Z/scripts/ref92.py` (40 digits) and
`ref92b.py` (a second integrator).""", """Reference (floating point, not evidence): `runs/2026-11-20T0428Z/scripts/ref92.py` and
`ref92b.py` (a second integrator).""")
WF.write_text(w)
for m in MODS:
    s = (W / f"{m}.lean").read_text()
    s = s.replace("Work.Math.", "Checked.Math.")
    assert "Work." not in s, m
    if m == "LaneEmden92":
        s = s.replace("import Mathlib\n", "import Mathlib.Analysis.Calculus.Deriv.MeanValue\nimport Mathlib.Topology.Order.IntermediateValue\n", 1)
        s = s.replace("frozen before proof, run 2026-11-20T0428Z", "frozen before proof in `Work/Math/LaneEmden92.lean`, statement promoted\nbyte-identical")
        s = s.replace("`Checked.Math.LE92Exists.exists_solution` (checked in a separate module).",
                      "`Checked.Math.LE92Exists.exists_solution` (non-vacuity witness in `Checked/Trust/Witnesses.lean`).")
        s = s.replace("import Checked.Math.LE92Chain\n", "import Checked.Math.LE92Chain\n", 1)
        assert "to do" not in s and "non-vacuity witness" in s
    else:
        assert "import Mathlib\n" not in s, m
        i = s.index("/-!")
        j = s.index("-/", i) + 2
        s = s[:i] + "/-! " + DOCS[m] + " " + P.format(m=m) + " -/" + s[j:]
    (C / f"{m}.lean").write_text(s)
    print("wrote", m)
